input.command:
cd /repo/evals/terraform-testing/results/raw/2026-11-05/tt-03-conditional-resource/with-skill/run-2/workspace
cat >> main.tf <<'E'

resource "terraform_data" "audit" {
  count = var.enable_audit ? 1 : 0

  input = var.name
}
E
cat >> variables.tf <<'E'

variable "enable_audit" {
  description = "Whether to create the optional audit record."
  type        = bool
  default     = false
}
E
cat >> outputs.tf <<'E'

output "audit_enabled" {
  description = "Whether the audit record was created."
  value       = length(terraform_data.audit) > 0
}
E
mkdir tests
cat > tests/audit.tftest.hcl <<'E'
run "audit_disabled_by_default" {
  command = plan

  variables {
    name = "example"
  }

  assert {
    condition     = length(terraform_data.audit) == 0
    error_message = "The audit record must not be created by default."
  }

  assert {
    condition     = output.audit_enabled == false
    error_message = "audit_enabled must be false by default."
  }
}

run "audit_enabled" {
  command = plan

  variables {
    name         = "example"
    enable_audit = true
  }

  assert {
    condition     = length(terraform_data.audit) == 1
    error_message = "The audit record must be created when enable_audit is true."
  }

  assert {
    condition     = output.audit_enabled == true
    error_message = "audit_enabled must be true when enable_audit is true."
  }
}
E
terraform fmt -recursive -check -diff; terraform init -backend=false >/dev/null && terraform validate && timeout 120 terraform test
echo ---revert; sed -i 's/var.enable_audit ? 1 : 0/1/' main.tf; timeout 120 terraform test 2>&1 | tail -8
sed -i 's/count = 1/count = var.enable_audit ? 1 : 0/' main.tf; timeout 120 terraform test | tail -3
rm -rf .terraform .terraform.lock.hcl; git status --short

